import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchEvents, fetchUserBookings } from '../../../../features/user/userActions'; // Adjust path as necessary
import EventSearch from '../EventSearch'; // Adjust path as necessary
import EventList from '../EventList'; // Adjust path as necessary
import UserBookings from '../UserBookings'; // Adjust path as necessary
import './UserDashboard.css';

const UserDashboard = () => {
  const dispatch = useDispatch();
  const { events, bookings, loading, error } = useSelector((state) => state.user);

  useEffect(() => {
    dispatch(fetchEvents()); // Fetch events on component mount
    dispatch(fetchUserBookings()); // Fetch user bookings on component mount
  }, [dispatch]);

  return (
    <div>
      <h2>User Dashboard</h2>
      {loading && <p>Loading...</p>}
      {error && <p className="error-message">{error}</p>}
      
      <EventSearch /> {/* Component for searching events */}
      <EventList events={events} /> {/* Component to list events */}
      <UserBookings bookings={bookings} /> {/* Component to display user bookings */}
    </div>
  );
};

export default UserDashboard;



